with deduped as (select * from (select *, row_number() over (partition by order_id order by amount desc nulls first, id) as dedup_rank from payments) x where dedup_rank = 1) select case when amount >= 1520 then 'HIGH' else 'LOW' end as amount_tier, count(*) as row_count, round(sum(amount) / nullif(count(case when status = 'FAILED' then 1 end), 0), 2) as amount_per_failed, count(*) filter (where method = 'card') as card_rows, (unix_timestamp(max(paid_at)) - unix_timestamp(min(paid_at))) / 60 as duration_min, (unix_timestamp(max(paid_at)) - unix_timestamp(min(paid_at))) / 60 as span_minutes from deduped group by 1 order by amount_tier nulls last
